#!/usr/bin/env bash
# Build the ChatGPT plugin submission ZIP for Wishfinity +W.
#
# Output: chatgpt-plugin/dist/wishfinity-plugin.zip  (a build artifact, gitignored)
#
# The ZIP holds plugin.json, mcp.json and assets/ at its root -- the layout
# OpenAI's "With MCP" plugin submission expects. chatgpt-app-submission.json is
# NOT placed in the ZIP; it is uploaded separately in the Apps submission form
# (and can be regenerated by OpenAI's `chatgpt-app-submission` skill).
set -euo pipefail
cd "$(dirname "$0")"

mkdir -p dist
rm -f dist/wishfinity-plugin.zip
zip -r dist/wishfinity-plugin.zip plugin.json mcp.json assets -x '.*' '*/.*'

echo "Built: $(pwd)/dist/wishfinity-plugin.zip"
unzip -l dist/wishfinity-plugin.zip
